{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Valdecoxib, a primary sulfonamide, has an absolute oral bioavailability of 83% in humans, demonstrating that sulfonamide-containing small molecules can achieve high systemic exposure after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Fasudil, a sulfonamide drug, has an absolute oral bioavailability of 69% in humans, supporting high oral bioavailability for sulfonamide chemotypes.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Sildenafil, a sulfonyl-containing drug, has an absolute oral bioavailability of 38% in adults, still well above the 20% threshold despite moderate first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Ziprasidone has an absolute oral bioavailability of 60% under fed conditions in humans, showing that even challenging lipophilic drugs can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Amrinone, a polar heteroaromatic drug, has an oral bioavailability of 90-95% in healthy subjects, indicating that polar ionizable structures can be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Levodopa, a polar amino acid, has an absolute oral bioavailability of 80.4% in healthy volunteers, supporting high oral bioavailability for polar small molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a benzothiadiazine sulfonamide (chlorothiazide-like). All relevant adult oral bioavailability records for sulfonamide-containing and polar small molecules exceed 20%, many with absolute F values of 38-83%. The only sub-20% record is enteral sildenafil in premature infants, which is not representative of adult oral dosing. Therefore F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself in the provided records.",
    "Most analogues are not thiazide diuretics; extrapolation relies on shared sulfonamide/polar features and high assay-transfer scores.",
    "Food effects and formulation differences are not fully controlled across records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

